import { chromium } from '@playwright/test'
import { mkdirSync, readFileSync } from 'node:fs'
import { pathToFileURL } from 'node:url'
mkdirSync('artifacts/design-data', { recursive: true })
const exe = process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE
const browser = await chromium.launch({ executablePath: exe, args: ['--no-sandbox'] })
const page = await browser.newPage({ viewport: { width: 720, height: 1200 } })
// load image via data URL into an <img>, get natural size
const b64 = readFileSync('artifacts/design-data.webp').toString('base64')
const dataUrl = 'data:image/webp;base64,' + b64
await page.setContent(`<html><body style="margin:0"><img id="im" src="${dataUrl}"></body></html>`)
await page.waitForFunction(()=>{const im=document.getElementById('im');return im && im.complete && im.naturalWidth>0})
const dim = await page.evaluate(()=>({w:document.getElementById('im').naturalWidth,h:document.getElementById('im').naturalHeight}))
console.log('DIMS', JSON.stringify(dim))
const b64out = 'x'
// Slice: put image at 720 wide, scroll and screenshot 720x1200 slices scaled to natural
await page.setViewportSize({ width: dim.w, height: 1200 })
const segs = Math.ceil(dim.h/1200)
for(let i=0;i<segs;i++){
  await page.evaluate(y=>window.scrollTo(0,y), i*1200)
  await page.waitForTimeout(200)
  await page.screenshot({ path:`artifacts/design-data/dseg${i}.png`, clip:{x:0,y:i*1200,width:dim.w,height:Math.min(1200,dim.h-i*1200)}, fullPage:true })
}
await browser.close()
console.log('DONE segs', segs)

