import { chromium } from '@playwright/test'
import { readFileSync } from 'node:fs'
const exe = process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE
const browser = await chromium.launch({ executablePath: exe, args: ['--no-sandbox'] })
const page = await browser.newPage({ viewport:{width:720,height:900} })
const b64 = readFileSync('artifacts/design-data.webp').toString('base64')
await page.setContent(`<html><body style="margin:0"><img id="im" src="data:image/webp;base64,${b64}" style="display:block;width:720px"></body></html>`)
await page.waitForFunction(()=>{const im=document.getElementById('im');return im&&im.complete&&im.naturalWidth>0})
const res = await page.evaluate(()=>{
  const im=document.getElementById('im'); const c=document.createElement('canvas'); c.width=im.naturalWidth; c.height=im.naturalHeight
  const ctx=c.getContext('2d'); ctx.drawImage(im,0,0)
  const W=im.naturalWidth,H=im.naturalHeight
  const data=ctx.getImageData(0,0,W,H).data
  const px=(x,y)=>{const i=(y*W+x)*4;return [data[i],data[i+1],data[i+2]]}
  const hex=(a)=>'#'+a.map(x=>x.toString(16).padStart(2,'0')).join('')
  // region scan: collect saturated colors (saturation high) in a box; return top colors by frequency excluding near-white/near-bg
  function scan(x0,y0,x1,y1){
    const counts=new Map()
    for(let y=y0;y<=y1;y+=2)for(let x=x0;x<=x1;x+=2){const [r,g,b]=px(x,y); const mx=Math.max(r,g,b),mn=Math.min(r,g,b); const sat=mx-mn; if(mx>250&&mn>250)continue; if(sat<25 && mx>200)continue; const k=hex([r,g,b]); counts.set(k,(counts.get(k)||0)+1)}
    return [...counts.entries()].sort((a,b)=>b[1]-a[1]).slice(0,6).map(e=>e[0]+'('+e[1]+')')
  }
  const R={}
  R.card1_num = scan(180,380,340,430)      // green big number 5258
  R.card2_num = scan(180,830,420,880)      // purple 65361.84
  R.card3_num = scan(170,790,320,840)      // will adjust
  R.card3_num2 = scan(150,745,320,800)
  R.card3_pill_dot_local = scan(120,860,150,890)
  R.card3_pill_dot_non = scan(150,860,180,890)
  R.public_pill_sel = scan(400,1090,540,1130)
  R.public_num_grid = scan(60,1290,300,1350)
  R.donut1 = scan(450,1450,620,1620)
  R.repair_num_green = scan(400,1690,560,1740)
  R.eval_progress = scan(80,2210,640,2235)
  R.rank_no1 = scan(80,4150,180,4200)
  R.rank_no4 = scan(80,4380,180,4430)
  R.ring = scan(540,4080,620,4180)
  return R
})
for(const [k,v] of Object.entries(res)) console.log(k, '=>', v.join('  '))
await browser.close()

import { chromium } from '@playwright/test'
import { readFileSync } from 'node:fs'
const exe = process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE
const browser = await chromium.launch({ executablePath: exe, args: ['--no-sandbox'] })
const page = await browser.newPage({ viewport:{width:720,height:900} })
const b64 = readFileSync('artifacts/design-data.webp').toString('base64')
await page.setContent(`<html><body style="margin:0"><img id="im" src="data:image/webp;base64,${b64}" style="display:block;width:720px"></body></html>`)
await page.waitForFunction(()=>{const im=document.getElementById('im');return im&&im.complete&&im.naturalWidth>0})
const res = await page.evaluate(()=>{
  const im=document.getElementById('im'); const c=document.createElement('canvas'); c.width=im.naturalWidth; c.height=im.naturalHeight
  const ctx=c.getContext('2d'); ctx.drawImage(im,0,0); const W=im.naturalWidth; const data=ctx.getImageData(0,0,W,im.naturalHeight).data
  const px=(x,y)=>{const i=(y*W+x)*4;return [data[i],data[i+1],data[i+2]]}
  const hex=a=>'#'+a.map(x=>x.toString(16).padStart(2,'0')).join('')
  // scan a horizontal line, return runs of distinct colors
  function line(y,x0,x1,step=4){ const out=[]; let prev=null; for(let x=x0;x<=x1;x+=step){const p=px(x,y); const h=hex(p); if(h!==prev){out.push(x+':'+h); prev=h}} return out.join(' ') }
  // vertical
  function vline(x,y0,y1,step=4){ const out=[]; let prev=null; for(let y=y0;y<=y1;y+=step){const p=px(x,y); const h=hex(p); if(h!==prev){out.push(y+':'+h); prev=h}} return out.join(' ') }
  return {
    pubToggleRow: line(1400, 300, 640, 6),   // 公共收益 pill row
    card1bg: vline(60, 340, 700, 10),        // card1 bg top->bottom at x=60
    card3pillsRow: line(870, 100, 640, 6),   // card3 pill row
    pubCellRow: line(1230, 60, 660, 10),     // 公共收益 first grid row cells
    evalBarRow: vline(120, 2280, 2320, 2),   // eval progress bar vertical thickness
  }
})
for(const [k,v] of Object.entries(res)) console.log('###',k,'\n',v,'\n')
await browser.close()

