// 完成率环颜色：>=80 绿，60-79 橙，<60 红
function ringColor(rate: number) { return rate >= 80 ? '#12b76a' : rate >= 60 ? '#f79009' : '#f04438' }
function ringStyle(rate: number) {
  const c = ringColor(rate)
  return {
    background: `conic-gradient(${c} ${rate * 3.6}deg, #e9edf3 ${rate * 3.6}deg)`,
  }
}
